"""Food / non-food classifier for product names from the price files.
Seeds: high-precision word lists. Model: naive Bayes on name words + manufacturer, self-trained.
usage: from foodclf import classify; classify(items) -> {code: p_food}"""
import re, math, collections

NONFOOD_W = {w.replace('_', ' ') for w in '''שמפו מרכך לשיער שיער סבון כביסה רחצה ספריי תחליב שיניים מברשת סרום לחות קרם_ידיים מסיר לניקוי ניקוי נוזל_כלים כלים
שפתון שפתיים עפרון מסקרה סומק קונסילר מייקאפ מייק גלוס פודרה איפור לק גבות צללית צללית אייליינר בושם אדפ אדט דאודורנט רול_און
צלחות צלחת כוסות_חד כוס_קרטון מפיות מפית נייר_טואלט טואלט מגבונים מטליות ספוג כפפות אשפה שקיות_אשפה אלומיניום נייר_כסף נייר_אפייה תבנית
נירוסטה סיליקון זכוכית_צנצנות פלסטיק סכו"ם מזלג כפית מחבת סיר קומקום מגהץ מייבש מכונת סוללה סוללות נורה נר נרות גפרורים מצית
חיתולים חיתול טיטולים מוצץ מוצצי פטמה בקבוק_תינוק משחת_החתלה טמפון טמפונים תחבושות פדים גילוח סכיני סכין מכונת_גילוח
חתולים לחתול לכלב לכלבים חתול כלב חול_לחתול אקונומיקה מבריק מטהר מפיג מסיר_כתמים אבקת_כביסה קפסולות_כביסה
צבע_לשיער קולור קרטין מסכה_לשיער משחה_לשיער ג'ל_לשיער וקס תמרוקים קוסמטיקה ויטמין תוסף_תזונה כמוסות טבליות
פריסקיז פורינה ויסקס פדיגרי קיטיקט רויאל_קנין פרו_פלאן מפרידי_אצבעות לקים טישו ממחטות סיגריות מרלבורו טבק עדשות_מגע עדשות כדורי_טניס כדור שטיח שטיחון אמבטיה מקלחת וילון תחליב_רחצה שמן_עיסוי שמן_גוף שמן_שפתיים שמן_לשיער שמן_תינוקות שמן_למאור נר_שבועי קסמי_שיניים אטמי_אוזניים בליסטקס משחה_לשפתיים ליפ_באלם מפת מפה כוסות_יין כוסות כוס_זכוכית כוסיות קערת קערה סט פחמים מדליק מגן למאור גביעי גביע_יין מטחנת_פלפל מטחנה_ידנית עיתון ידיעות מגזין פיין_קט פרמיו מועך פותחן מקלף מסננת קולפן זרעים לגינה צעצוע משחק בובה חולצה גרביים מגבת שמיכה כרית מצעים עציץ אגרטל באנר דגל בלונים קישוט מטאטא מגב דלי סמרטוט'''.split()}
FOOD_W = {w.replace('_', ' ') for w in '''חלב גבינה גבינת יוגורט שמנת חמאה חמאת מעדן ביצים לחם לחמניות פיתה פיתות עוגה עוגת עוגיות ביסקוויט וופל קרקר פריכיות
חטיף חטיפי שוקולד סוכריות ממתק מסטיק גלידה ארטיק ריבה ממרח דבש טחינה חומוס סלט רוטב קטשופ מיונז חרדל תבלין פפריקה כמון פלפל מלח
סוכר קמח אורז פסטה ספגטי פתיתים קוסקוס אטריות נודלס דגני קורנפלקס גרנולה שיבולת שמן_זית זיתים מלפפונים חמוצים טונה סרדינים
דג סלמון אמנון בשר עוף הודו שניצל קציצות המבורגר נקניקיות נקניק סלמי פסטרמה כבד מרק פירה פלאפל בורקס פיצה מאפה בצק לזניה
ירקות פירות תפוח בננה תות ענבים תמרים צימוקים אגוזים שקדים בוטנים גרעינים פיסטוק קשיו קוקוס משקה מיץ נקטר סירופ תה קפה קקאו
שוקו סודה קולה מים_מינרליים טופו תירס אפונה שעועית עדשים חומוס פטריות עגבניות רסק בצל שום גזר תפו"א חלבון קינוח פודינג
בירה יין וודקה ויסקי ליקר ערק קוניאק שמפניה מוצרלה גאודה פטה בולגרית קוטג' לבנה לבן עיזים סושי בייגלה ציפס במבה ביסלי
זעתר פשתן צ'יה קינואה כוסמין דייסה מחית מחיות פחזניות הרינג קטניות תבלינים פריגת שוופס אנטריקוט סטייק צלעות אסאדו נתחי
שמן_חמניות שמן_קנולה שמן_סויה שמן_תירס שמן_שומשום מזוכך אורזו פסטה מטרנה סימילאק נוטרילון תמ"ל תרכובת_מזון סוכרזית ממתיק
נספרסו קפסולות_קפה קפסולות_קפסו אספרסו אבקת_שתייה פתיבר נוטלה ממרח_שוקולד קרם_נוגט נוצולה פופקורן סוכרלוז סטיביה ממתיק_נוזלי'''.split()}
FOOD_W -= {'לבן'}

# מילים שמכריעות בוודאות שהמוצר אינו מזון, גם אם המודל חושב אחרת
HARD_NONFOOD = {'מועך', 'למאור', 'שפתון', 'פותחן', 'מקלף', 'קולפן', 'עיתון', 'סיגריות', 'טבק', 'שמפו', 'דאודורנט', 'אקונומיקה'}

def toks(name):
    n = re.sub(r'\d+([.,]\d+)?', ' ', name)
    return [w for w in re.findall(r'[א-תA-Za-z"\']{2,}', n) if w not in ('גרם', 'גר', 'מל', 'מ"ל', 'יח', "יח'", 'ליטר', 'ק"ג', 'קג', 'מארז', 'יחידות')]

def bigrams(ws): return [a + ' ' + b for a, b in zip(ws, ws[1:])]

def feats(x):
    ws = toks(x['name']); f = ws + bigrams(ws)
    man = re.sub(r'\s+', ' ', x.get('man') or '').strip(' ,.-')
    if man and man not in ('---', 'כללי', 'לא ידוע', '-', ','): f.append('M:' + man)
    return f

def seed(x):
    ws = toks(x['name']); s = set(ws) | set(bigrams(ws))
    nf, fd = bool(s & NONFOOD_W), bool(s & FOOD_W)
    TOOLS = {'מועך', 'למאור', 'פותחן', 'מקלף', 'מסננת', 'קולפן', 'מטחנה ידנית', 'כוסות יין', 'מפת', 'נר', 'נרות'}
    if s & TOOLS or s & HARD_NONFOOD: return 0
    if nf and not fd: return 0
    if fd and not nf: return 1
    return None

def classify(items, rounds=3):
    F = [feats(x) for x in items]
    lab = [seed(x) for x in items]
    for r in range(rounds):
        cnt = [collections.Counter(), collections.Counter()]; n = [1, 1]
        for f, l in zip(F, lab):
            if l is None: continue
            n[l] += 1; cnt[l].update(set(f))
        V = len(set(cnt[0]) | set(cnt[1])) or 1
        def p(f):
            lo = math.log(n[1] / n[0])
            for t in set(f):
                if t in cnt[0] or t in cnt[1]:
                    w = 3 if t.startswith('M:') else 1
                    lo += w * (math.log((cnt[1][t] + .5) / (n[1] + V * .5)) - math.log((cnt[0][t] + .5) / (n[0] + V * .5)))
            return 1 / (1 + math.exp(-max(-30, min(30, lo))))
        P = [p(f) for f in F]
        seeds = [seed(x) for x in items]
        lab = [s if s is not None else (1 if q > .97 else 0 if q < .03 else None) for s, q in zip(seeds, P)]
    return [0.0 if (set(toks(x['name'])) | set(bigrams(toks(x['name'])))) & HARD_NONFOOD else q for x, q in zip(items, P)]
